SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `poi_entertainment`;
CREATE TABLE `poi_entertainment` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `source` varchar(32) NOT NULL DEFAULT 'amap' COMMENT '数据源',
  `source_id` varchar(64) NOT NULL COMMENT '高德POI ID',
  `name` varchar(256) NOT NULL DEFAULT '' COMMENT '名称',
  `alias` varchar(512) DEFAULT '' COMMENT '别名',
  `biz_category` varchar(64) DEFAULT '' COMMENT '业务分类',
  `query_label` varchar(128) DEFAULT '' COMMENT '采集分类名称',
  `query_types` varchar(128) DEFAULT '' COMMENT '采集高德类型',
  `type` varchar(512) DEFAULT '' COMMENT '高德类型文本',
  `typecode` varchar(128) DEFAULT '' COMMENT '高德类型码',
  `keytag` varchar(256) DEFAULT '' COMMENT '高德细分类标签',
  `province` varchar(64) DEFAULT '' COMMENT '省份',
  `city` varchar(64) DEFAULT '' COMMENT '城市',
  `district` varchar(64) DEFAULT '' COMMENT '区县',
  `adcode` varchar(16) DEFAULT '' COMMENT '行政区划编码',
  `business_area` varchar(128) DEFAULT '' COMMENT '商圈',
  `address` varchar(512) DEFAULT '' COMMENT '地址',
  `lng` varchar(32) DEFAULT '' COMMENT '经度',
  `lat` varchar(32) DEFAULT '' COMMENT '纬度',
  `coord_type` varchar(32) DEFAULT 'gcj02' COMMENT '坐标系',
  `tel` varchar(256) DEFAULT '' COMMENT '电话',
  `rating` decimal(4,1) DEFAULT NULL COMMENT '评分',
  `cost` decimal(10,2) DEFAULT NULL COMMENT '人均/价格',
  `open_time` varchar(256) DEFAULT '' COMMENT '营业时间',
  `opentime2` varchar(512) DEFAULT '' COMMENT '完整营业时间',
  `entertainment_type` varchar(64) DEFAULT '' COMMENT '娱乐细分类',
  `seat_ordering` tinyint DEFAULT NULL COMMENT '是否支持订座/选座',
  `groupbuy_num` int DEFAULT '0' COMMENT '团购数',
  `discount_num` int DEFAULT '0' COMMENT '优惠数',
  `indoor_map` tinyint DEFAULT NULL COMMENT '是否有室内地图',
  `indoor_data` json DEFAULT NULL COMMENT '楼层/室内信息',
  `children` json DEFAULT NULL COMMENT '子POI',
  `photos` json DEFAULT NULL COMMENT '图片列表',
  `head_image` varchar(512) DEFAULT '' COMMENT '头图',
  `parent` varchar(64) DEFAULT '' COMMENT '父POI',
  `entr_location` varchar(64) DEFAULT '' COMMENT '入口坐标',
  `navi_poiid` varchar(128) DEFAULT '' COMMENT '导航POI ID',
  `website` varchar(512) DEFAULT '' COMMENT '网站',
  `raw` json DEFAULT NULL COMMENT '高德原始JSON',
  `status` tinyint DEFAULT '0' COMMENT '0正常 1失效',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_id` (`source_id`),
  KEY `idx_geo` (`lng`,`lat`),
  KEY `idx_adcode` (`adcode`),
  KEY `idx_typecode` (`typecode`),
  KEY `idx_entertainment_type` (`entertainment_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='休闲娱乐POI表';

